async function action(fn:()=>Promise<void>){setMessage('');setBusy(true);try{await fn()}catch(e:any){setMessage(e.message||'Unable to complete this action.')}finally{setBusy(false)}}
async function reloadAdmin(){const d=await call('/api/admin');setAdmin(d);setSettingsText(JSON.stringify(d.settings,null,2));}
function pickNetwork(id:number){setChainId(id);setInvoice(null);setWallet(null);setWalletPicker(false)}
async function connect(selected:Data){await action(async()=>{const sol=chainId===0;let address,signature;const provider=selected.provider;if(sol){const result=await provider.connect();const publicKey=result?.publicKey||provider.publicKey;if(!publicKey)throw new Error('Wallet did not return a Solana address.');address=publicKey.toString();}else{address=(await provider.request({method:'eth_requestAccounts'}))[0];}const c=await call('/api/wallet/challenge',{address,chainId});if(sol){const result=await provider.signMessage(new TextEncoder().encode(c.message),'utf8');const {default:bs58}=await import('bs58');signature=bs58.encode(result.signature||result);}else signature=await provider.request({method:'personal_sign',params:[c.message,address]});await call('/api/wallet/verify',{nonce:c.nonce,signature});setWallet({...selected,address,sol});setWalletPicker(false);await refresh();});}
function availableWallets(){if(chainId!==0)return walletOptions;const w=window as any;return [[w.phantom?.solana,'Phantom'],[w.solflare,'Solflare'],[w.backpack?.solana,'Backpack']].filter(([p])=>p?.connect&&p?.signMessage&&p?.signAndSendTransaction).map(([provider,name])=>({provider,info:{name,uuid:name}}));}
async function purchase(mode:'wallet'|'direct'='wallet'){if(!me){window.location.href='/signin';return;}if(mode==='wallet'&&(!wallet||wallet.sol!==(chainId===0))){if(chainId!==0&&!walletOptions.length&&(window as any).ethereum)setWalletOptions([{info:{name:'Browser wallet',uuid:'injected'},provider:(window as any).ethereum}]);setWalletPicker(true);return;}await action(async()=>{const data=await call('/api/payments/quote',{pay,chainId,mode});setInvoice(data);setTxHash('');});}
async function sendPayment(){await action(async()=>{if(!wallet||!invoice)throw new Error('Reconnect your payment wallet.');if(new Date(invoice.expires).getTime()<=Date.now())throw new Error('Quote expired. Get a new quote.');let hash;if(invoice.chain_id===0){if(wallet.provider.publicKey?.toString()!==invoice.wallet)throw new Error('Choose the wallet used for this invoice.');const data=await call('/api/payments/solana/transaction',{orderId:invoice.id});const {Transaction}=await import('@solana/web3.js');const transaction=Transaction.from(Uint8Array.from(atob(data.transaction),c=>c.charCodeAt(0)));const result=await wallet.provider.signAndSendTransaction(transaction);hash=typeof result==='string'?result:result.signature;}else{await wallet.provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+invoice.chain_id.toString(16)}]});const accounts=await wallet.provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==invoice.wallet)throw new Error('Choose the wallet used for this invoice.');hash=await wallet.provider.request({method:'eth_sendTransaction',params:[{from:invoice.wallet,to:invoice.treasury,value:'0x'+BigInt(invoice.wei).toString(16)}]});}setTxHash(hash);localStorage.setItem('mint_pending_invoice',JSON.stringify({orderId:invoice.id,txHash:hash}));setMessage('Payment submitted. Confirming on-chain…');for(let attempt=0;attempt<12;attempt++){try{await call('/api/payments/verify',{orderId:invoice.id,txHash:hash});localStorage.removeItem('mint_pending_invoice');setInvoice(null);await refresh();setMessage('Payment confirmed. Your credit is ready.');return}catch(error:any){if(!/finality|pending/i.test(error?.message||''))throw error;await new Promise(resolve=>setTimeout(resolve,2500));}}setMessage('Payment received. Credit will appear automatically after network finality.');});}
