function compactCalculator(){const selected=brand.packages.find(p=>p.pay===pay)||brand.packages[1];return <div className="calculator compact-calculator"><div className="buy-heading"><h2>Buy API credit</h2><span>Pay as you go</span></div><label>Choose your credit</label><div className="compact-packages" role="group" aria-label="Choose API credit amount">{brand.packages.map(p=><button type="button" aria-pressed={pay===p.pay} className={pay===p.pay?'chosen':''} onClick={()=>{setPay(p.pay);setInvoice(null)}} key={p.pay}><strong>${p.credit}</strong><span>credit</span></button>)}</div><div className="compact-value"><div><span>You pay</span><strong>${selected.pay}</strong></div><span className="value-arrow">→</span><div><span>You get</span><strong>${selected.credit}</strong></div></div><div className="network-tabs" role="group" aria-label="Payment network">{[[1,'Ethereum'],[4663,'Robinhood'],[0,'Solana']].map(([id,name])=><button type="button" key={id} aria-pressed={chainId===id} className={chainId===id?'active':''} onClick={()=>{pickNetwork(Number(id))}}><span>◆</span> {name}</button>)}</div><div className="payment-actions"><button className="button lime full" disabled={busy||!pub?.purchasing} onClick={()=>purchase('wallet')}>{pub?.purchasing?'Pay with wallet':'Purchases opening soon'} <span>↗</span></button><button className="button full" disabled={busy||!pub?.purchasing} onClick={()=>purchase('direct')}>Pay to address <span>↗</span></button></div><p className="compact-note">Choose either method · Routers automatically detects confirmed direct transfers</p></div>}
